import React, { useState } from 'react';
import { ThemeProvider, CssBaseline, Box, Fade } from '@mui/material';
import '@fontsource/inter/300.css';
import '@fontsource/inter/400.css';
import '@fontsource/inter/500.css';
import '@fontsource/inter/600.css';
import '@fontsource/inter/700.css';

import { theme } from './theme/theme';
import Header from './components/Layout/Header';
import Home from './components/Pages/Home';
import Monitor from './components/Pages/Monitor';
import About from './components/Pages/About';

function App() {
  const [currentTab, setCurrentTab] = useState(0);

  const handleTabChange = (event, newValue) => {
    setCurrentTab(newValue);
  };

  const renderContent = () => {
    const pages = [
      <Home key="home" />,
      <Monitor key="monitor" />,
      <About key="about" />
    ];

    return (
      <Fade in={true} timeout={500} key={currentTab}>
        <Box>
          {pages[currentTab]}
        </Box>
      </Fade>
    );
  };

  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <Box
        sx={{
          minHeight: '100vh',
          background: currentTab === 0 
            ? 'transparent' // Para la página Home que tiene su propia imagen de fondo
            : 'linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%)', // Fondo elegante para otras páginas
        }}
      >
        <Header currentTab={currentTab} onTabChange={handleTabChange} />
        {renderContent()}
      </Box>
    </ThemeProvider>
  );
}

export default App;
